// === routes/menu.js ===
import { Router } from 'express';
const menu = [{ id: 1, nama: 'Kopi Susu' }, { id: 2, nama: 'Teh Tarik' }];
const router = Router();
router.get('/', (req, res) => res.json(menu));
router.get('/:id', (req, res) => {
  const m = menu.find((x) => x.id === Number(req.params.id));
  if (!m) return res.status(404).json({ error: 'Menu tidak ada' });
  res.json(m);
});
export default router;
// === routes/pesanan.js ===
import { Router } from 'express';
const router = Router();
router.get('/', (req, res) => res.json({ jalur: req.baseUrl + req.path, pesanan: [] }));
export default router;
// === app.js ===
import express from 'express';
import menuRouter from './routes/menu.js';
import pesananRouter from './routes/pesanan.js';
export const app = express();
app.use(express.json());
app.use('/api/v1/menu', menuRouter);
app.use('/api/v1/pesanan', pesananRouter);
// === main.js ===
import { app } from './app.js';
const server = app.listen(3000);
const u = 'http://localhost:3000/api/v1';
console.log((await (await fetch(u + '/menu')).json()).length);
console.log(await (await fetch(u + '/menu/2')).json());
console.log(await (await fetch(u + '/pesanan')).json());
console.log((await fetch('http://localhost:3000/menu')).status);
server.close();

