import express from 'express';
const router = express.Router();
router.get('/ping', (req, res) => res.send('pong'));
const app = express();
app.use('/api', router);
const server = app.listen(3000);
console.log(await (await fetch('http://localhost:3000/api/ping')).text());
server.close();
